#!/usr/bin/env python3

import binascii
import re
from itertools import cycle

def xor_with_key(data, key):
    """XOR the data with the given key."""
    return bytes(b ^ k for b, k in zip(data, cycle(key)))

def guess_key_from_pattern(ciphertext, pattern_pos, known_pattern):
    """Guess the key at the given position assuming a known plaintext."""
    key_len = len(known_pattern)
    key = bytearray(key_len)

    for i in range(key_len):
        if pattern_pos + i < len(ciphertext):
            key[i] = ciphertext[pattern_pos + i] ^ known_pattern[i]

    return bytes(key)

def extract_potential_flags(decrypted):
    """Extract potential flags from the decrypted text."""
    flags = []

    # Try to decode as UTF-8
    try:
        decoded = decrypted.decode('utf-8', errors='replace')
        # Find all matches for flag pattern
        matches = re.finditer(r'flag\{[^}]*\}', decoded)
        for match in matches:
            flags.append(match.group(0))
    except:
        pass

    # Binary search approach for incomplete flags
    start_idx = 0
    while True:
        start = decrypted.find(b'flag{', start_idx)
        if start == -1:
            break

        end = decrypted.find(b'}', start)
        if end == -1:
            # If we can't find the closing bracket, include a reasonable amount of text
            end = min(start + 50, len(decrypted))
            flags.append(decrypted[start:end].decode('utf-8', errors='replace') + "...}")
        else:
            flags.append(decrypted[start:end+1].decode('utf-8', errors='replace'))

        start_idx = start + 1

    return flags

def test_key_with_offsets(data, key):
    """
    Test a key by trying it at different offsets in the ciphertext.
    This helps find where the key might correctly align.
    """
    results = []
    key_len = len(key)

    # Try different alignments of the key
    for offset in range(key_len):
        # Rotate the key to create a different alignment
        rotated_key = key[offset:] + key[:offset]
        decrypted = xor_with_key(data, rotated_key)

        # Look for flag patterns
        flags = extract_potential_flags(decrypted)
        if flags:
            for flag in flags:
                results.append((offset, rotated_key, flag, decrypted))

    return results

def main():
    # Read the encrypted data
    with open('/home/ctfplayer/ctf_files/encrypted', 'r') as f:
        hex_data = f.read().strip()

    # Convert hex to bytes
    data = binascii.unhexlify(hex_data)

    print(f"Data length: {len(data)} bytes")

    # Check the description data as a key
    description_hex = "274c10121a0100495b502d551c557f0b0833585d1b27030b5228040d3753490a1c025415051525455118001911534a0052560a14594f0b1e490a010c4514411e070014615a181b02521b580305170002074b0a1a4c414d1f1d171d00151b1d0f480e491e0249010c150050115c505850434203421354424c1150430b5e094d144957080d4444254643"
    description_data = binascii.unhexlify(description_hex)

    print("\nTesting if the description itself is a clue or part of the key...")
    # A repeating XOR usually has a small key, so let's try different sizes
    for key_len in range(1, 30):
        key = description_data[:key_len]
        decrypted = xor_with_key(data, key)
        flags = extract_potential_flags(decrypted)
        if flags:
            print(f"Found potential flags using key of length {key_len} from description:")
            print(f"Key: {key.hex()}")
            for flag in flags:
                print(f"Flag: {flag}")

    # Search for 'flag{' pattern at different positions to derive keys
    print("\nSearching for 'flag{' pattern at different offsets...")
    flag_pattern = b'flag{'

    for offset in range(len(data) - len(flag_pattern)):
        potential_key = bytearray(data[offset:offset+len(flag_pattern)])
        for i in range(len(flag_pattern)):
            potential_key[i] ^= flag_pattern[i]

        key = bytes(potential_key)

        # Try different key lengths that are multiples of the pattern length
        for multiple in range(1, 6):
            if multiple == 1:
                extended_key = key
            else:
                extended_key = key * multiple

            decrypted = xor_with_key(data, extended_key)
            flags = extract_potential_flags(decrypted)

            if flags:
                print(f"\nPotential key at offset {offset} (length {len(extended_key)}):")
                print(f"Key: {extended_key.hex()}")
                for flag in flags:
                    print(f"Flag: {flag}")

                # Check the surrounding text for context
                flag_start = decrypted.find(b'flag{')
                if flag_start != -1:
                    context_start = max(0, flag_start - 10)
                    flag_end = decrypted.find(b'}', flag_start)
                    if flag_end == -1:
                        flag_end = flag_start + 50
                    else:
                        flag_end += 1
                    context_end = min(len(decrypted), flag_end + 10)

                    try:
                        context = decrypted[context_start:context_end].decode('utf-8', errors='replace')
                        print(f"Context: ...{context}...")
                    except:
                        pass

    # Test specific key lengths that showed promise in our previous analysis
    print("\nTesting specific key lengths that showed promise...")
    promising_lengths = [3, 5, 16, 18, 19]

    for key_len in promising_lengths:
        # Try simple single-byte and two-byte keys first
        for i in range(256):
            single_byte = bytes([i])
            key = single_byte * key_len
            decrypted = xor_with_key(data, key)
            flags = extract_potential_flags(decrypted)
            if flags:
                print(f"\nFound potential flag with single-byte key (length {key_len}):")
                print(f"Key: {key.hex()}")
                for flag in flags:
                    print(f"Flag: {flag}")

        # Look for keys by assuming 'flag{' appears at the start of a block
        for offset in range(len(data) - len(flag_pattern)):
            # Only check offsets that align with the key
            if offset % key_len == 0:
                # Derive the key bytes from the known pattern
                derived_key = bytearray(key_len)
                for i in range(len(flag_pattern)):
                    pos = (offset + i) % key_len
                    derived_key[pos] = data[offset + i] ^ flag_pattern[i]

                # Fill in remaining key bytes with 0
                for i in range(len(derived_key)):
                    if derived_key[i] == 0:
                        derived_key[i] = ord('X')  # Use 'X' as a placeholder

                key = bytes(derived_key)
                results = test_key_with_offsets(data, key)

                for key_offset, tested_key, flag, decrypted in results:
                    print(f"\nFound potential flag with derived key (length {key_len}, offset {offset}):")
                    print(f"Key: {tested_key.hex()}")
                    print(f"Flag: {flag}")

                    # Try to find complete working keys for promising results
                    if 'flag{' in flag and '}' in flag:
                        # Refine the key by analyzing the whole decryption
                        flag_start = decrypted.find(b'flag{')
                        flag_end = decrypted.find(b'}', flag_start)
                        if flag_end > flag_start:
                            flag_text = decrypted[flag_start:flag_end+1]
                            print(f"Complete flag: {flag_text.decode('utf-8', errors='replace')}")

                            # Check the text before and after the flag
                            if flag_start > 0:
                                before = decrypted[max(0, flag_start-20):flag_start]
                                try:
                                    print(f"Text before flag: {before.decode('utf-8', errors='replace')}")
                                except:
                                    pass

                            if flag_end < len(decrypted) - 1:
                                after = decrypted[flag_end+1:min(len(decrypted), flag_end+21)]
                                try:
                                    print(f"Text after flag: {after.decode('utf-8', errors='replace')}")
                                except:
                                    pass

    # Check if the encrypted data itself has a pattern
    print("\nChecking for repeating patterns in the encrypted data...")
    for pattern_len in range(2, 21):
        # Check if we have a repeating pattern
        chunks = [data[i:i+pattern_len] for i in range(0, len(data) - pattern_len, pattern_len)]
        repeats = {}

        for i, chunk in enumerate(chunks):
            if chunk in repeats:
                repeats[chunk].append(i * pattern_len)
            else:
                repeats[chunk] = [i * pattern_len]

        # Report chunks that repeat
        repeating = {k: v for k, v in repeats.items() if len(v) > 1}
        if repeating:
            print(f"Found repeating patterns of length {pattern_len}:")
            for chunk, positions in repeating.items():
                print(f"  Pattern: {chunk.hex()}, positions: {positions}")
                print(f"  Distances: {[positions[i+1] - positions[i] for i in range(len(positions)-1)]}")

    # Look at key frequency to potentially identify the key length
    print("\nAnalyzing character frequency in the ciphertext...")
    for key_len in range(2, 21):
        # Split into groups that would be XORed with the same key byte
        groups = [[] for _ in range(key_len)]
        for i, byte in enumerate(data):
            groups[i % key_len].append(byte)

        # Check frequency distribution in each group
        for i, group in enumerate(groups):
            freq = {}
            for byte in group:
                if byte in freq:
                    freq[byte] += 1
                else:
                    freq[byte] = 1

            # Sort by frequency
            sorted_freq = sorted(freq.items(), key=lambda x: x[1], reverse=True)

            # Only show the most frequent bytes
            if sorted_freq and sorted_freq[0][1] > 1:
                print(f"Group {i} (key pos {i}) - Most frequent bytes: " +
                      ", ".join([f"0x{b:02x} ({count})" for b, count in sorted_freq[:3]]))

if __name__ == "__main__":
    main()

