#!/usr/bin/env python3

import binascii
import string
from itertools import cycle
from collections import Counter
import numpy as np
import re

def hamming_distance(a, b):
    """Calculate the Hamming distance between two byte strings."""
    assert len(a) == len(b)
    return sum(bin(x ^ y).count('1') for x, y in zip(a, b))

def find_key_length(data, max_keylen=30):
    """Try to find the key length using normalized Hamming distance."""
    distances = {}

    for keylen in range(2, max_keylen + 1):
        # Take multiple blocks to get better average
        blocks = [data[i:i+keylen] for i in range(0, len(data) - keylen * 2, keylen)]
        if len(blocks) < 2:
            continue

        # Calculate hamming distance between consecutive blocks
        dist = 0
        pairs = 0
        for i in range(len(blocks) - 1):
            for j in range(i + 1, min(i + 4, len(blocks))):
                if len(blocks[i]) == len(blocks[j]):
                    dist += hamming_distance(blocks[i], blocks[j])
                    pairs += 1

        if pairs > 0:
            # Normalize by dividing by keylen and number of pairs
            distances[keylen] = dist / (keylen * pairs)

    # Sort by distance (lowest first)
    sorted_distances = sorted(distances.items(), key=lambda x: x[1])
    return sorted_distances

def xor_with_key(data, key):
    """XOR the data with the given key."""
    return bytes(b ^ k for b, k in zip(data, cycle(key)))

def score_text(text):
    """Score text based on character frequency in English."""
    # Common English letters frequency
    english_freq = {
        'e': 12.7, 't': 9.1, 'a': 8.2, 'o': 7.5, 'i': 7.0, 'n': 6.7, 's': 6.3,
        'h': 6.1, 'r': 6.0, 'd': 4.3, 'l': 4.0, 'u': 2.8, 'c': 2.8, 'm': 2.4,
        'w': 2.4, 'f': 2.2, 'g': 2.0, 'y': 2.0, 'p': 1.9, 'b': 1.5, 'v': 1.0,
        'k': 0.8, 'j': 0.2, 'x': 0.2, 'q': 0.1, 'z': 0.1, ' ': 13.0
    }

    try:
        decoded = text.decode('utf-8', errors='replace').lower()
    except:
        return -1

    # Count printable characters
    printable_count = sum(1 for c in decoded if c in string.printable)
    if len(decoded) == 0:
        return -1

    printable_ratio = printable_count / len(decoded)

    # If less than 70% printable, reject
    if printable_ratio < 0.7:
        return -1

    # Calculate character frequency score
    char_counts = Counter(decoded)
    total_chars = sum(char_counts.values())

    score = 0
    for char, freq in english_freq.items():
        expected = freq / 100 * total_chars
        observed = char_counts.get(char, 0)
        score -= abs(expected - observed)

    # Bonus for flag pattern
    if 'flag{' in decoded:
        score += 500

    return score

def find_repeating_xor_key(data, key_length):
    """Find the repeating XOR key of given length."""
    # Split data into blocks corresponding to each key byte
    blocks = [[] for _ in range(key_length)]
    for i, byte in enumerate(data):
        blocks[i % key_length].append(byte)

    # Convert blocks to bytes
    blocks = [bytes(block) for block in blocks]

    # Find the most likely key byte for each position
    key = bytearray(key_length)
    for i, block in enumerate(blocks):
        scores = []
        for k in range(256):
            # XOR the block with this byte
            decrypted = bytes(b ^ k for b in block)
            score = score_text(decrypted)
            scores.append((k, score))

        # Select the byte with the highest score
        key[i] = max(scores, key=lambda x: x[1])[0]

    return bytes(key)

def log_keepers():
    print("\n3. Brute-force with English language frequency analysis and flag pattern matching...")

    promising_keys = [
        # Keys derived from previous attempts (named after the offsets they were found at)
        bytes.fromhex("7d4b626c29"),  # Key from offset 20 - gave flag{UOo[z4A~n}
        bytes.fromhex("2f667d652f"),  # Key from offset 30 - gave flag{:ch@j~~}
        bytes.fromhex("6c78382870"),  # Key from offset 50 - gave flag{r12)|)ly6wllYrhwzj3(o}
        bytes.fromhex("78256b6677"),  # Key from offset 55 - gave flag{=1*xpx1<oc'9}
        bytes.fromhex("237820797c"),  # Key from offset 60 - gave flag{#lA#d8zrb$ }
        bytes.fromhex("6569766779"),  # Key from offset 75 - gave flag{b"|}

        # keys from ASCII combinations of common CTF patterns
        b'xor_k',
        b'xorct',
        b'xor==',
        b'ctf20',
        b'key==',
        b'A_key',
        b'flagg',
    ]

    return promising_keys

def main():
    # Read the encrypted data
    with open('/home/ctfplayer/ctf_files/encrypted', 'r') as f:
        hex_data = f.read().strip()

    # Convert hex to bytes
    data = binascii.unhexlify(hex_data)

    print(f"Encrypted data size: {len(data)} bytes")

    print("\n1. Analyzing potential key lengths using Hamming distance...")
    key_lengths = find_key_length(data)
    print("Top 10 potential key lengths (normalized distance):")
    for keylen, distance in key_lengths[:10]:
        print(f"Key length {keylen}: {distance:.4f}")

    print("\n2. Checking for repeating patterns in the data...")
    # Look for repeating sequences
    min_pattern_length = 3
    max_pattern_length = 10
    patterns = {}

    for pattern_len in range(min_pattern_length, max_pattern_length + 1):
        for i in range(len(data) - pattern_len):
            pattern = data[i:i+pattern_len]
            for j in range(i + pattern_len, len(data) - pattern_len + 1):
                if data[j:j+pattern_len] == pattern:
                    distance = j - i
                    if pattern not in patterns:
                        patterns[pattern] = []
                    patterns[pattern].append(distance)

    # Filter patterns with multiple occurrences and calculate GCDs
    filtered_patterns = {p: distances for p, distances in patterns.items() if len(distances) > 1}

    if filtered_patterns:
        print(f"Found {len(filtered_patterns)} repeating patterns with multiple occurrences")

        # Calculate GCDs of distances to find potential key lengths
        from math import gcd
        from functools import reduce

        def calculate_gcd(numbers):
            if len(numbers) == 1:
                return numbers[0]
            return reduce(gcd, numbers)

        # Count occurrences of each GCD
        gcd_counts = {}
        for pattern, distances in filtered_patterns.items():
            if len(distances) > 1:
                distances_gcd = calculate_gcd(distances)
                if distances_gcd not in gcd_counts:
                    gcd_counts[distances_gcd] = 0
                gcd_counts[distances_gcd] += 1

        # Show most common GCDs
        print("Most common GCDs of pattern distances (potential key lengths):")
        for gcd_value, count in sorted(gcd_counts.items(), key=lambda x: x[1], reverse=True)[:5]:
            print(f"GCD {gcd_value}: {count} occurrences")
    else:
        print("No repeating patterns found")

    # Try most promising key lengths from Hamming distance analysis
    for keylen, _ in key_lengths[:5]:
        print(f"\nAttempting to find key of length {keylen}...")
        key = find_repeating_xor_key(data, keylen)
        print(f"Potential key (hex): {key.hex()}")

        # Decrypt with this key
        decrypted = xor_with_key(data, key)

        try:
            decoded = decrypted.decode('utf-8', errors='replace')
            printable_ratio = sum(c in string.printable for c in decoded) / len(decoded)
            print(f"Printable character ratio: {printable_ratio:.2f}")

            # Look for flag pattern
            if 'flag{' in decoded:
                flag_matches = re.findall(r'flag\{[^}]*\}', decoded)
                for flag in flag_matches:
                    print(f"Found flag pattern: {flag}")

            # Display a sample of the decrypted text
            if printable_ratio > 0.7:
                print(f"Sample of decrypted text: {decoded[:100]}")
        except:
            print("Failed to decode result as UTF-8")

    # Try with promising keys
    promising_keys = log_keepers()
    for key in promising_keys:
        print(f"\nTrying promising key: {key.hex()}")
        decrypted = xor_with_key(data, key)

        try:
            decoded = decrypted.decode('utf-8', errors='replace')
            printable_ratio = sum(c in string.printable for c in decoded) / len(decoded)
            print(f"Printable ratio: {printable_ratio:.2f}")

            if 'flag{' in decoded:
                flag_matches = re.findall(r'flag\{[^}]*\}', decoded)
                for flag in flag_matches:
                    print(f"Found flag pattern: {flag}")

                    # Display some context around the flag
                    flag_start = decoded.find(flag)
                    context_start = max(0, flag_start - 10)
                    context_end = min(len(decoded), flag_start + len(flag) + 10)
                    context = decoded[context_start:context_end]
                    print(f"Context: ...{context}...")
        except:
            print("Failed to decode result as UTF-8")

    # Try a pure brute force with common CTF-related key patterns for 5-byte keys
    print("\n4. Trying common CTF-related patterns for 5-byte keys...")

    # Generate keys from common words in CTF crypto challenges
    keywords = ['xor', 'key', 'flag', 'ctf', 'crypt', 'cyber', 'hack', 'sec']

    for word in keywords:
        # Try variations: word alone, word padded, etc.
        variations = [
            word.encode(),
            word.upper().encode(),
            (word + '_').encode(),
            ('_' + word).encode()
        ]

        # Ensure key length is 5 by truncating or padding
        for var in variations:
            # Skip if it's too long for the inner loop to handle
            if len(var) > 5:
                continue

            # Pad to 5 bytes
            if len(var) < 5:
                padded = var + b'_' * (5 - len(var))
                variations.append(padded)

        for key in variations:
            if len(key) == 5:  # Only use keys of length 5
                decrypted = xor_with_key(data, key)
                try:
                    decoded = decrypted.decode('utf-8', errors='replace')
                    if 'flag{' in decoded:
                        flag_matches = re.findall(r'flag\{[^}]*\}', decoded)
                        if flag_matches:
                            print(f"Key {key.hex()} ({key.decode()}) gives flag: {flag_matches[0]}")
                except:
                    pass

    # Try what we've learned from the challenge name "another_xor"
    another_key = b'anthr'  # Shortened form of "another"
    print(f"\nTrying 'anthr' from 'another_xor' challenge name...")
    decrypted = xor_with_key(data, another_key)
    try:
        decoded = decrypted.decode('utf-8', errors='replace')
        print(f"First 100 chars: {decoded[:100]}")
        if 'flag{' in decoded:
            flag_matches = re.findall(r'flag\{[^}]*\}', decoded)
            for flag in flag_matches:
                print(f"Found flag pattern: {flag}")
    except:
        print("Failed to decode result as UTF-8")

if __name__ == "__main__":
    main()

