#!/usr/bin/env python3

import binascii
import re
import string

def read_hex_file():
    with open("/home/ctfplayer/ctf_files/encrypted", "r") as f:
        return f.read().strip()

def xor_single_byte(data, key_byte):
    """XOR each byte in data with key_byte"""
    return bytes(b ^ key_byte for b in data)

def is_printable(text):
    """Check if text is mostly printable ASCII"""
    printable_count = sum(1 for c in text if c in string.printable)
    return printable_count / len(text) > 0.8

def main():
    # Read and convert the hex data
    hex_data = read_hex_file()
    encrypted = binascii.unhexlify(hex_data)

    # Check if the description is actually the encrypted data
    print(f"First 20 bytes of hex: {hex_data[:40]}")

    # Try all possible single-byte keys
    for key_byte in range(256):
        decrypted = xor_single_byte(encrypted, key_byte)

        try:
            text = decrypted.decode("utf-8", errors="replace")

            # Only print promising results
            if "flag" in text.lower() or is_printable(text):
                print(f"\nKey byte 0x{key_byte:02x} (ASCII: {chr(key_byte) if 32 <= key_byte <= 126 else 'non-printable'}):")
                print("-" * 50)
                print(text[:100] + "..." if len(text) > 100 else text)

                flag_match = re.search(r'flag\{[^}]*\}', text, re.IGNORECASE)
                if flag_match:
                    flag = flag_match.group(0)
                    print(f"Found possible flag: {flag}")

        except Exception as e:
            continue

if __name__ == "__main__":
    main()
